INSERT INTO testimonials (name, brand_name, quote, related_opportunity_id) VALUES ('বিনিয়োগকারী', 'উত্তরবঙ্গ বাটিক হাউজ', 'ইনশা আল্লাহ্ এই সপ্তাহের মধ্যে বিনিয়োগ করবো।ভালো লেগেছে উনাদেরকে।', (SELECT id FROM opportunities WHERE name ILIKE 'উত্তরবঙ্গ বাটিক হাউজ' LIMIT 1));
INSERT INTO testimonials (name, brand_name, quote, related_opportunity_id) VALUES ('বিনিয়োগকারী', 'One Ummah BD', 'One ummah bd খুব ক্যাশ ক্রাইসিসে আছে। অতিরিক্ত দ্রুত বড় করে ব্যাবসা নিয়ে ভালো বিপাকে পড়েছে।', (SELECT id FROM opportunities WHERE name ILIKE 'One Ummah BD' LIMIT 1));
INSERT INTO testimonials (name, brand_name, quote, related_opportunity_id) VALUES ('বিনিয়োগকারী', 'শাহী ভ্যারাইটি স্টোর', 'ALHAMDULILLAH, আমি শাহী ভ্যারাইটি স্টোরে বিনিয়োগ করেছি, এবং আমার অভিজ্ঞতা এখন পর্যন্ত খুবই ইতিবাচক। প্রতিষ্ঠানটি নিয়মিত ও স্বচ্ছভাবে কার্যক্রম পরিচালনা করে, এবং আমি সন্তোষজনক মুনাফা পেয়েছি। প্রতিষ্ঠাতা মাহির (সাইফ) দায়িত্বশীল এবং বিনিয়োগকারীদের সঙ্গে আন্তরিকভাবে যোগাযোগ রাখেন, যা আমার আস্থা আরও বাড়িয়েছে।  আমার ব্যক্তিগত অভিজ্ঞতার ভিত্তিতে বলতে পারি, শাহী ভ্যারাইটি স্টোর একটি সম্ভাবনাময় প্রতিষ্ঠান। এই ইতিবাচক অভিজ্ঞতার কারণে ভবিষ্যতেও আমি এখানে আরও বিনিয়োগ করতে আগ্রহী। প্রতিষ্ঠানটির উত্তরোত্তর সাফল্য ও সমৃদ্ধি কামনা করছি।', (SELECT id FROM opportunities WHERE name ILIKE 'শাহী ভ্যারাইটি স্টোর' LIMIT 1));
