INSERT INTO testimonials (name, brand_name, quote, related_opportunity_id) VALUES ('বিনিয়োগকারী', 'পজিটিভ বাজার', 'আমি বিনিয়োগ করেছি। উনার ব্যবহার কথাবার্তা অমায়িক পজিটিভ মাইন্ডের। আশা করি ইনশাল্লাহ তার থেকে ভালো কিছু পাব।  যতটুকু বুঝতে পারতেছি উনি আস্তে ধীরে আগাচ্ছে তাড়াহুড়া কম করে। প্রোডাক্ট খুব ভালো', (SELECT id FROM opportunities WHERE name ILIKE 'পজিটিভ বাজার' LIMIT 1));
