INSERT INTO testimonials (name, brand_name, quote, related_opportunity_id) VALUES ('বিনিয়োগকারী', 'মেড ইজি', 'মাত্র ১ মাস আগে বিনিয়োগ করেছি। মতামত জানানোর সময় আসেনি এখনো', (SELECT id FROM opportunities WHERE name ILIKE 'মেড ইজি' LIMIT 1));
INSERT INTO testimonials (name, brand_name, quote, related_opportunity_id) VALUES ('বিনিয়োগকারী', 'Mawazin', 'তাদের প্রতিষ্ঠান এ আমার ৩ লাখ টাকার ইনভেস্টমেন্ট করা ১ বছর হইছে, যেটার মেয়াদ পূর্ন হলেও প্রজেক্ট ক্লোজ করতে পারে নি এখনো, যদিও প্রফিট মার্জিন অনেক কমিয়ে তারা এখন ওই প্রজেক্ট রানিং রেখেছে।(তাদের ইন্টারন্যাল বিভিন্ন ইস্যুর কারণে)। আর একটা সর্ট প্রজেক্ট ৩/৪ মাস মেয়াদি ছিল সেখানেও ৩ লাখ টাকা ইনভেস্টমেন্ট করেছিলাম তবে প্রজেক্ট এর টাইম লাইন শেষ হলেও মূল টাকা ফেরত পেতে বেশ বেগ পেতে হয়েছে।  উল্লেখ্য তাদের ওইখানে আমার ইনভেস্টমেন্ট করা আসলে তাদের ই আরেকটা ইনভেস্টমেন্ট WhatsApp Group থেকে আপনাদের মাদ্ধমে নয়। আর তারা দাবি করে ইসলামি শরিয়া মতে এবং শরিয়া কন্সাল্টেন্সি আছে নাকি যেটা আসলেই বিশ্বাস যোগ্য মনে হয় নি।', (SELECT id FROM opportunities WHERE name ILIKE 'Mawazin' LIMIT 1));
