INSERT INTO testimonials (name, brand_name, quote, related_opportunity_id) VALUES ('বিনিয়োগকারী', 'Tasneem Knitting', 'আলহামদুলিল্লাহ অনেক ভালো মানুষ। প্রকৃত ব্যবসায়িক জ্ঞানের অধিকারী। তাদের কাজের মান, পেশাদারিত্ব এবং ভবিষ্যৎ পরিকল্পনা সত্যিই প্রশংসনীয়। আশা করি সততা ও দক্ষতার মাধ্যমে প্রতিষ্ঠানটি আরও অনেক দূর এগিয়ে যাবে। সাফল্য অব্যাহত থাকুক। বর্তমানে শেখার জন্য তার সাথে আমি চায়না অবস্থান করছি।', (SELECT id FROM opportunities WHERE name ILIKE 'Tasneem Knitting' LIMIT 1));
