INSERT INTO testimonials (name, brand_name, quote, related_opportunity_id) VALUES ('বিনিয়োগকারী', 'উত্তরবঙ্গ বাটিক হাউজ', 'উনাদের ব্যবহার বেশ ভালো। আমার অনেক প্রশ্ন ছিল সময় নিয়ে উত্তর দিয়েছেন। মাস শেষে সময়মত হিসাব ও টাকা বুঝিয়ে দেন। উনাদের ব্যবসা হলো টিপিকাল ব্যবসা, উনাদের থেকে খুব একটা প্রফেশনালিসম আশা করি না। তবে যতটুকু আছে যথেষ্ট। উনাদের ব্যবসার ভবিষ্যতের ব্যপারে আমি আশাবাদি।', (SELECT id FROM opportunities WHERE name ILIKE 'উত্তরবঙ্গ বাটিক হাউজ' LIMIT 1));
INSERT INTO testimonials (name, brand_name, quote, related_opportunity_id) VALUES ('বিনিয়োগকারী', 'One Ummah BD', 'উনাদের সব কিছুই আমার কাছে চমৎকার লেগেছে। অত্যন্ত প্রফেশনালি তারা সব হ্যান্ডেল করেন। হিসাব নিকাশ থেকে শুরু করে উনারা সব ব্যপারেই সবকিছু বিনিয়োগকারীদের কাছে শেয়ার করেন। উনাদের ৬ মাস পর পর বিনিয়োগকারীদের নিয়ে যে মিটিং হয় সেটা আমার কাছে চমৎকার লেগেছে।', (SELECT id FROM opportunities WHERE name ILIKE 'One Ummah BD' LIMIT 1));
INSERT INTO testimonials (name, brand_name, quote, related_opportunity_id) VALUES ('বিনিয়োগকারী', 'শাহী ভ্যারাইটি স্টোর', 'সবচেয়ে ভালো লেগেছে শাহী স্টোরে বিনিয়োগ করে। কারণ বিনিয়োগকারীদের সাথে যোগাযোগ ভালো রাখেন। গ্যাপ নাই।', (SELECT id FROM opportunities WHERE name ILIKE 'শাহী ভ্যারাইটি স্টোর' LIMIT 1));
INSERT INTO testimonials (name, brand_name, quote, related_opportunity_id) VALUES ('বিনিয়োগকারী', 'Food Pallet', 'বিনিয়োগ করতে চেয়েছিলাম কিন্তু উনাদের নিকট কিছু তথ্য চেয়েছি উনারা দেয়নি।', (SELECT id FROM opportunities WHERE name ILIKE 'Food Pallet' LIMIT 1));
INSERT INTO testimonials (name, brand_name, quote, related_opportunity_id) VALUES ('বিনিয়োগকারী', 'আহমেদ মোটরস', 'এই প্রতিষ্ঠানের সবচেয়ে যেটা ভাল লেগেছে সেটা হলো যেদিন থেকে টাকা বিনিয়োগ করেছি সেদিন থেকেই লভ্যাংশ হিসাব করেছে। লভ্যাংশ নিয়মিত দিচ্ছে এবং লভ্যাংশের হার ও বেশ আকর্ষণীয়। আলমগীর কবির ভাই বেশ পরিশ্রমী এবং হিসাব নিকাশ ও পরিষ্কার।', (SELECT id FROM opportunities WHERE name ILIKE 'আহমেদ মোটরস' LIMIT 1));
INSERT INTO testimonials (name, brand_name, quote, related_opportunity_id) VALUES ('বিনিয়োগকারী', 'গাড়ীয়াল', 'এই মানুষ টা ব্যক্তি হিসাবে যতেষ্ট ভালো। ওনার একটা গুণ খুবই ভালো নিজেই ইনভেস্টার খোজ খবর নেন।যতেষ্টা আন্তরিক। ধন্যবাদ মেরাজ ভাই ❤️❤️❤️', (SELECT id FROM opportunities WHERE name ILIKE 'গাড়ীয়াল' LIMIT 1));
INSERT INTO testimonials (name, brand_name, quote, related_opportunity_id) VALUES ('বিনিয়োগকারী', 'বানু এন্টারপ্রাইস', 'Better', (SELECT id FROM opportunities WHERE name ILIKE 'বানু এন্টারপ্রাইস' LIMIT 1));
INSERT INTO testimonials (name, brand_name, quote, related_opportunity_id) VALUES ('বিনিয়োগকারী', 'Food Network Agro', 'আলহামদুলিল্লাহ, তিনি একজন অসাধারণ মানুষ। তবে যোগাযোগের ক্ষেত্রে কিছুটা ধীরগতি লক্ষ্য করা যায়। তিনি বিনয়ী ও সৎ। এভাবে সততা, বিনয় এবং সুন্দর নেতৃত্বের মাধ্যমে এগিয়ে গেলে ইনশাআল্লাহ অনেক দূর যেতে পারবেন।', (SELECT id FROM opportunities WHERE name ILIKE 'Food Network Agro' LIMIT 1));
INSERT INTO testimonials (name, brand_name, quote, related_opportunity_id) VALUES ('বিনিয়োগকারী', 'পজিটিভ বাজার', 'হিসেব ঠিকঠাক দেয় না। মুনাফা দিতে দেরী করে। কথা ও কাজের মিল কম। খুবই অসন্তুষ্ট। মনে হচ্ছে বিনিয়োগ করে ভুল করেছি।', (SELECT id FROM opportunities WHERE name ILIKE 'পজিটিভ বাজার' LIMIT 1));
