INSERT INTO testimonials (name, brand_name, quote, related_opportunity_id) VALUES ('বিনিয়োগকারী', 'পজিটিভ বাজার', 'উনার কমিটম্যান্ট রক্ষার ব্যাপারে উদাসীনতা পেয়েছি আমি ইনভেস্ট এখানো করিনি করতে চাই কিন্তু কিছুটা ভিতি কাজ করছে।', (SELECT id FROM opportunities WHERE name ILIKE 'পজিটিভ বাজার' LIMIT 1));
