INSERT INTO testimonials (name, brand_name, quote, related_opportunity_id) VALUES ('বিনিয়োগকারী', 'Mawazin', 'আমি Mawazin-এ বিনিয়োগ করেছি। তাদের রেসপন্স ভালো এবং পলিসি সন্তোষজনক। তবে ডিড কমপ্লিটের সময় তারা বলেছিল কাপ্তাই লেক প্রকল্প ১৫ জুলাই থেকে শুরু হবে, কিন্তু আজ ২৭ জুলাই হয়ে গেলেও প্রকল্পটি শুরু হয়নি। আমি ৮ জুলাই বিনিয়োগ করেছি, কিন্তু প্রকল্প শুরুতে বিলম্ব হচ্ছে।', (SELECT id FROM opportunities WHERE name ILIKE 'Mawazin' LIMIT 1));
