INSERT INTO testimonials (name, brand_name, quote, related_opportunity_id) VALUES ('বিনিয়োগকারী', 'গাড়ীয়াল', 'তিনি ব্যবসায়ের মালিকানাও শেয়ার করছেন, এটা ভালো দিক। ১০% ডিস্কাউন্ট দিচ্ছেন শুনে আগ্রহী হলাম। তবে তার ব্যবসায়ের Valuation তিনি নিজেই করেছেন এমনটা জানালেন উদ্যোক্তা। এ ধরনের ভ্যালুয়েশন কতটা গ্রহণযোগ্য আমার জানা নেই। আর গ্রুপে জানানো হয়েছিল, উদ্যোক্তা সার্বক্ষণিক সিসি ক্যামেরা এক্সেস দিবেন বিনিয়োগকারীদেরকে। তাঁকে এ ব্যাপারে জিজ্ঞেস করাতে তিনি বললেন, এখনো সিসিটিভি লাগানোই হয় নাই। তো দুই জায়গায় দুই ধরনের কথা পাওয়ায় এ ক্ষেত্রে আর বিনিয়োগ করা হয়ে ওঠে নাই।', (SELECT id FROM opportunities WHERE name ILIKE 'গাড়ীয়াল' LIMIT 1));
