INSERT INTO testimonials (name, brand_name, quote, related_opportunity_id) VALUES ('বিনিয়োগকারী', 'উত্তরবঙ্গ বাটিক হাউজ', 'উনার সাথেও বিনিয়োগ করে ভালো লাগলো। তবে এখনো বিনিয়োগ এর লভ্যাংশ পাই নি। তবে কথা বলে ভালো লেগেছে এবং দ্রুত সমস্যা সমাধান এর চেষ্টা করে এবং বিনিয়োগকারীদের গুরুত্ব দিয়ে বিবেচনা করে। উনার জন্যও অনেক শুভকামনা রইলো।', (SELECT id FROM opportunities WHERE name ILIKE 'উত্তরবঙ্গ বাটিক হাউজ' LIMIT 1));
INSERT INTO testimonials (name, brand_name, quote, related_opportunity_id) VALUES ('বিনিয়োগকারী', 'One Ummah BD', 'মাশাআল্লাহ্, ভাল প্রতিষ্ঠান।', (SELECT id FROM opportunities WHERE name ILIKE 'One Ummah BD' LIMIT 1));
INSERT INTO testimonials (name, brand_name, quote, related_opportunity_id) VALUES ('বিনিয়োগকারী', 'শাহী ভ্যারাইটি স্টোর', 'এখনো পর্যন্ত খুব ভালো লেগেছে আমার উনাকে। খুবই প্রফেশনাল লেগেছে। কথা আর কাজে মিল আছে। আমি সন্তুষ্ট। এভাবে থাকলে বিনিয়োগকারীরা আরও আগ্রহ বোধ করবে উনার সাথে কাজ করার জন্য।', (SELECT id FROM opportunities WHERE name ILIKE 'শাহী ভ্যারাইটি স্টোর' LIMIT 1));
INSERT INTO testimonials (name, brand_name, quote, related_opportunity_id) VALUES ('বিনিয়োগকারী', 'পজিটিভ বাজার', 'প্রফেশনাল না। কথা কাজের মিল নাই। ভবিষ্যতে বিনিয়োগ করার ইচ্ছা নাই।', (SELECT id FROM opportunities WHERE name ILIKE 'পজিটিভ বাজার' LIMIT 1));
