INSERT INTO testimonials (name, brand_name, quote, related_opportunity_id) VALUES ('বিনিয়োগকারী', 'মেড ইজি', 'উনাকে যথেষ্ট প্রফেশনাল মনেহয়েছে।হিসাব গুলো সম্ভবত সফটওয়্যার নির্ভর এবং নিখুঁত মনে হয়েছে', (SELECT id FROM opportunities WHERE name ILIKE 'মেড ইজি' LIMIT 1));
INSERT INTO testimonials (name, brand_name, quote, related_opportunity_id) VALUES ('বিনিয়োগকারী', 'Mawazin', 'Mawazin-এর উত্তরোত্তর সাফল্য কামনা করি। ইনশাআল্লাহ, মিজানুর  ভাইয়ের  পরিশ্রম ও সততার ফল আরও বড় অর্জন বয়ে আনবে। শুভকামনা রইল।', (SELECT id FROM opportunities WHERE name ILIKE 'Mawazin' LIMIT 1));
