INSERT INTO testimonials (name, brand_name, quote, related_opportunity_id) VALUES ('বিনিয়োগকারী', 'One Ummah BD', 'প্রফেশনাল।  টাকা ডিসবার্সমেন্ট টা আরো দ্রুত করা দরকার', (SELECT id FROM opportunities WHERE name ILIKE 'One Ummah BD' LIMIT 1));
INSERT INTO testimonials (name, brand_name, quote, related_opportunity_id) VALUES ('বিনিয়োগকারী', 'শাহী ভ্যারাইটি স্টোর', 'আলহামদুলিল্লাহ, ব্যবসায়িক অংশীদারিত্ব আমার জন্য সত্যিই কল্যাণকর হয়েছে। সততা, আন্তরিকতা এবং পেশাদারিত্ব আমার আস্থা আরও দৃঢ় করেছে।', (SELECT id FROM opportunities WHERE name ILIKE 'শাহী ভ্যারাইটি স্টোর' LIMIT 1));
INSERT INTO testimonials (name, brand_name, quote, related_opportunity_id) VALUES ('বিনিয়োগকারী', 'পজিটিভ বাজার', 'কর্তৃপক্ষ খুবই অপেশাদার।', (SELECT id FROM opportunities WHERE name ILIKE 'পজিটিভ বাজার' LIMIT 1));
