INSERT INTO testimonials (name, brand_name, quote, related_opportunity_id) VALUES ('বিনিয়োগকারী', 'মেড ইজি', 'হাইলি প্রফেশনাল, সবকিছু ঠিকঠাক কুইক সল্যুশন', (SELECT id FROM opportunities WHERE name ILIKE 'মেড ইজি' LIMIT 1));
INSERT INTO testimonials (name, brand_name, quote, related_opportunity_id) VALUES ('বিনিয়োগকারী', 'Mawazin', 'প্রতিষ্ঠাতা ভদ্রলোকের সাথে আলাপ হয় নাই। তবে গ্রুপ থেকে recommended একজন মহিলার সাথে আলাপ হয়েছিল। খাদ্যপণ্যের ব্যবসায় হওয়ায় তাঁর কাছে বিএসটিআই, TIN, BIN, Incorporation Certificate, Form XII এসব আছে কিনা দেখতে চাইলাম (বিনিয়োগকৃত অন্যান্য প্রতিষ্ঠানেও আমি এগুলো চেয়েছি এবং যার যে কয়টা আছে সেটা পেয়েছি)। এক্ষেত্রে, তিনি বললেন কাপ্তাই লেক থেকে মাছ এনে ঢাকায় বিক্রয় করা হবে বিধায় এসব দেখার নাকি প্রয়োজন নেই আর দেখার প্রয়োজন পড়লে যেন মোহাইমিন পাটোয়ারী ভাইয়ের কাছ থেকে দেখে নেই। চুক্তিপত্রের কিছু সংশোধন প্রস্তাবেও (যা অন্যত্র গৃহীত হয়েছে) তিনি অনড় ছিলেন। তাই স্বচ্ছতা ও বিনিয়োগের নিরাপত্তার ব্যাপারে নিশ্চিত হতে না পারায় ইচ্ছা থাকলেও এখানে বিনিয়োগ করা হয়ে ওঠে নাই।', (SELECT id FROM opportunities WHERE name ILIKE 'Mawazin' LIMIT 1));
INSERT INTO testimonials (name, brand_name, quote, related_opportunity_id) VALUES ('বিনিয়োগকারী', 'উত্তরবঙ্গ বাটিক হাউজ', 'কথা বার্তা বলে ভালো লেগেছে। পরবর্তীতে ইচ্ছে আছে।', (SELECT id FROM opportunities WHERE name ILIKE 'উত্তরবঙ্গ বাটিক হাউজ' LIMIT 1));
