INSERT INTO testimonials (name, brand_name, quote, related_opportunity_id) VALUES ('বিনিয়োগকারী', 'আমার ফুডস', 'The spokesperson seems responsible, honest and organized  so far. I would like to observe one year and provide further comment.', (SELECT id FROM opportunities WHERE name ILIKE 'আমার ফুডস' LIMIT 1));
INSERT INTO testimonials (name, brand_name, quote, related_opportunity_id) VALUES ('বিনিয়োগকারী', 'মেড ইজি', 'ফার্মা সেক্টর এর কম্পানি যার প্রয়োজনীয়তা সারা বছর সমান থাকে বিনিয়োগ পরিমান বেশি। আমি বিনিয়োগ এ আগ্রহী।', (SELECT id FROM opportunities WHERE name ILIKE 'মেড ইজি' LIMIT 1));
INSERT INTO testimonials (name, brand_name, quote, related_opportunity_id) VALUES ('বিনিয়োগকারী', 'Mawazin', 'বিনিয়োগ করার পর এখনো বেশি সময় হয়নি, তাই বর্তমানে কোনো প্রফিট পাওয়া যায়নি। যেহেতু এটি একটি বড় প্রতিষ্ঠান এবং তাদের ব্যবসায়িক ভিশন অনেক বড়, তাই দীর্ঘমেয়াদে তাদের সম্ভাবনা নিয়ে আমি আশাবাদী। তবে ব্যবসার প্রতি আরও আস্থা ও স্বচ্ছতা তৈরি করার জন্য নিয়মিত অডিট, আধুনিক ব্যবস্থাপনা এবং ডিজিটালাইজেশনের দিকে আরও বেশি গুরুত্ব দেওয়া প্রয়োজন বলে মনে হচ্ছে।  কিছুটা অহংকারী লক্ষ্য করেছিবিনিয়োগ করার সময় অতিরিক্ত ৬০০ টাকা নেওয়া হবে—এই বিষয়টি আগে জানানো হয়নি। আমি এর আগে যেসব জায়গায় বিনিয়োগ করেছি, সেখানে মালিক পক্ষই সাধারণত কুরিয়ার ও ডকুমেন্ট সংক্রান্ত খরচ বহন করেছে। তাই এ ধরনের অতিরিক্ত খরচ সম্পর্কে বিনিয়োগের আগে পরিষ্কারভাবে জানানো হলে আরও ভালো হতো।', (SELECT id FROM opportunities WHERE name ILIKE 'Mawazin' LIMIT 1));
