INSERT INTO testimonials (name, brand_name, quote, related_opportunity_id) VALUES ('বিনিয়োগকারী', 'আমার ফুডস', 'পলাশ সাহেবকে আমার কাছে বেশ এডুকেটেড মনে হয়েছে। মিতভাষী কিন্তু আন্তরিক হিসাবে পেয়েছি।', (SELECT id FROM opportunities WHERE name ILIKE 'আমার ফুডস' LIMIT 1));
INSERT INTO testimonials (name, brand_name, quote, related_opportunity_id) VALUES ('বিনিয়োগকারী', 'মেড ইজি', 'জুলাই-২৬ এ প্রথম ইনভেস্ট করেছি।।আরেফিন ভাই কে প্রফেশনাল মনে হয়েছে।। এবং প্রতিষ্ঠান এর সারভিস ও তুলনামূলক ভাবে ভালো লেগেছে।।', (SELECT id FROM opportunities WHERE name ILIKE 'মেড ইজি' LIMIT 1));
