INSERT INTO testimonials (name, brand_name, quote, related_opportunity_id) VALUES ('বিনিয়োগকারী', 'আমার ফুডস', 'উনি সম্ভব এনালগ পদ্ধতিতে হিসাব করেন।উনার উচিৎ সফটওয়্যার নির্ভর ব্যাবসা করা তাহলে হিসাব আরও নিখুঁত হবে।', (SELECT id FROM opportunities WHERE name ILIKE 'আমার ফুডস' LIMIT 1));
