INSERT INTO testimonials (name, brand_name, quote, related_opportunity_id) VALUES ('বিনিয়োগকারী', 'মেড ইজি', 'সবচেয়ে Professional এবং Rational মনে হয়েছে তাঁকে। জনাব আরেফিন জামানের সাথে শুধু ভয়েস ম্যাসেজ ও চ্যাটে কথা হয়েছে; কলেও কথা হয়নি আর দেখা হওয়া তো না-ই। তবু এখানে আমি আমার বিনিয়োগসমূহের মধ্যে সর্বোচ্চ এমাউন্ট দীর্ঘতম সময়ের জন্য করেছি, আলহামদুলিল্লাহ। কারণ, চুক্তিপত্রের স্বচ্ছতা, উদ্যোক্তার Flexibility, Accountability এবং কোম্পানি প্রোফাইল। চুক্তিপত্রের কিছু সংশোধনী প্রস্তাব খুব সহজেই যেমন গ্রহণ করেছেন আবার ১ টি প্রস্তাব গ্রহণে যৌক্তিকভাবে দ্বিমত পোষণ করেছেন যেটি তাঁর পেশাদারিত্ব ফুটিয়ে তুলেছে।', (SELECT id FROM opportunities WHERE name ILIKE 'মেড ইজি' LIMIT 1));
INSERT INTO testimonials (name, brand_name, quote, related_opportunity_id) VALUES ('বিনিয়োগকারী', 'আমার ফুডস', 'এফ এম জি সেক্টরের কম্পানি ঝুকি কম চাহিদা সব সময়।বিনিয়োগ করেছি আরো করব ইনশাআল্লাহ।', (SELECT id FROM opportunities WHERE name ILIKE 'আমার ফুডস' LIMIT 1));
INSERT INTO testimonials (name, brand_name, quote, related_opportunity_id) VALUES ('বিনিয়োগকারী', 'মেড ইজি', 'I am satisfied with Medeasy. Their service & response is very good.', (SELECT id FROM opportunities WHERE name ILIKE 'মেড ইজি' LIMIT 1));
INSERT INTO testimonials (name, brand_name, quote, related_opportunity_id) VALUES ('বিনিয়োগকারী', 'আমার ফুডস', 'একজন ভদ্র মার্জিত এবং সৎ ব্যক্তি বলেই আমার কাছে মনে হয়েছে। মুনাফার টাকা নিজ উদ্যোগে নক করে পাঠিয়ে দিয়েছেন। দিন তারিখের ব্যাপারে ওনাকে সিরিয়াস লেগেছে। এবং প্রফিট অন্য জায়গার তুলনায় কম হলেও, ব্যবসায় ঝুঁকিও কম। পরামর্শ থাকছে যে প্রফিট শেয়ারটা ৪০/৬০ না করে যদি ৫০/৫০ করতে পারেন, তাহলে আরেকটু বেটার ডিল হত ইনশাআল্লাহ।', (SELECT id FROM opportunities WHERE name ILIKE 'আমার ফুডস' LIMIT 1));
INSERT INTO testimonials (name, brand_name, quote, related_opportunity_id) VALUES ('বিনিয়োগকারী', 'মেড ইজি', 'আচার-ব্যবহার ভালো, পেশাদারিত্ব বজায় রেখে কাজ করেন।', (SELECT id FROM opportunities WHERE name ILIKE 'মেড ইজি' LIMIT 1));
INSERT INTO testimonials (name, brand_name, quote, related_opportunity_id) VALUES ('বিনিয়োগকারী', 'আমার ফুডস', 'উনাদের হোয়াটসঅ্যাপ গ্রুপ অনলি মি করে রাখছে। এতে আমরা যারা বিনিয়োগ করছি তারা কোনো আলোচনা চাইলে করার সুযোগ নাই। প্রতি মাসে কোনো হিসাব দেয়না।', (SELECT id FROM opportunities WHERE name ILIKE 'আমার ফুডস' LIMIT 1));
INSERT INTO testimonials (name, brand_name, quote, related_opportunity_id) VALUES ('বিনিয়োগকারী', 'মেড ইজি', 'Did not invest yet but planning to invest. Overall it seems to me this can be a good place for investment as the company is established already.', (SELECT id FROM opportunities WHERE name ILIKE 'মেড ইজি' LIMIT 1));
INSERT INTO testimonials (name, brand_name, quote, related_opportunity_id) VALUES ('বিনিয়োগকারী', 'আমার ফুডস', 'আলহামদুলিল্লাহ, উনাদের রেসপন্স ভালো।চুক্তি অনুযায়ী সব এখন পর্যন্ত ঠিকঠাক আছে।কোন কিছু জানতে চাইলে রেসপন্স পাই।', (SELECT id FROM opportunities WHERE name ILIKE 'আমার ফুডস' LIMIT 1));
INSERT INTO testimonials (name, brand_name, quote, related_opportunity_id) VALUES ('বিনিয়োগকারী', 'আমার ফুডস', 'ব্যবহার আলহামদুলিল্লাহ খুব ভালো। এখন পর্যন্ত সব ঠিকঠাক আছে।', (SELECT id FROM opportunities WHERE name ILIKE 'আমার ফুডস' LIMIT 1));
