INSERT INTO testimonials (name, brand_name, quote, related_opportunity_id) VALUES ('বিনিয়োগকারী', 'আমার ফুডস', 'কথা এবং  কাজে যতেষ্ট মিল।তার কমিউনিকেশন যতেষ্ট ভালো।', (SELECT id FROM opportunities WHERE name ILIKE 'আমার ফুডস' LIMIT 1));
INSERT INTO testimonials (name, brand_name, quote, related_opportunity_id) VALUES ('বিনিয়োগকারী', 'আমার ফুডস', 'প্রতিষ্ঠানটি ওয়েল ডকুমেন্টেড। প্রতিষ্ঠাতা সজ্জন বলেই মনে হয়। প্রতি মাসে প্রফিট শেয়ার করছেন চুক্তি মাফিক। গ্রুপে প্রতি মাসিক একটা হিসাবও শেয়ার করছেন। শুধু তাদের সেলস একটিভিটি টা ভিজুয়াল না। তাদের তেমন মার্কেটিং একটিভিটি বোঝা যায় না এবং লোকালি খবর নিয়ে দেখেছি তাদের প্রডাক্টও খুব পরিচিত নয় তার ডিস্ট্রিবিউট এলাকায়। বাট মাসিক সেলস দেখাচ্ছেন ৪০ লাখ প্লাস এটাই একটু খটকা। বিনিয়োগ বৃদ্ধি এডমিন প্যানেলকে অনুরোধ করবো তাদের দেয়া মাসিক সেলস রিপোর্ট টা সারপ্রাইজ অডিট করতে। ধন্যবাদ', (SELECT id FROM opportunities WHERE name ILIKE 'আমার ফুডস' LIMIT 1));
INSERT INTO testimonials (name, brand_name, quote, related_opportunity_id) VALUES ('বিনিয়োগকারী', 'আমার ফুডস', 'পলাশ ভাই কে অত্যন্ত বিনম্র মনে হয়েছে।।উনার ব্যবসা বানিজ্য নিয়ে বিস্তারিত বলেছেন যেটা আমার কাছে ভালো লেগেছে।। সমস্ত ডকুমেন্টস আপডেট করা আছে।।সুন্দর উপস্থাপনা উনার।।উনার এইখানে ও আমি জুলাই থেকে ইনভেস্ট করেছি।।', (SELECT id FROM opportunities WHERE name ILIKE 'আমার ফুডস' LIMIT 1));
