INSERT INTO testimonials (name, brand_name, quote, related_opportunity_id) VALUES ('বিনিয়োগকারী', 'আমার ফুডস', 'আমার ফুড নির্দিষ্ট টাইম প্রেমের মধ্যে ইনভেস্টদেরকে প্রফিট প্রদান করছেনা আমি মনে করি এটা একটা কমিটমেন্টের ঘাটতি উদাহরণস্বরূপ প্রতিমাসের ১৬ তারিখে আমার এক মাস পূর্ণ হয় সেই হিসেবে পরবর্তী 10 দিনের মধ্যে অর্থাৎ ২৬ তারিখের মধ্যে আমার একাউন্টে প্রফিট ডিপোজিট করার কথা। কিন্তু সেটি ডিপোজিট করা হয়েছে তার সেটি তার পরবর্তী এক মাসের ১ তারিখ। এভাবে প্রত্যেক মাসে দেরী করা হয়। আশা করি মহাইমিন ভাই এ ব্যাপারে যথাযথ পদক্ষেপ নেবেন', (SELECT id FROM opportunities WHERE name ILIKE 'আমার ফুডস' LIMIT 1));
INSERT INTO testimonials (name, brand_name, quote, related_opportunity_id) VALUES ('বিনিয়োগকারী', 'আমার ফুডস', 'Invested 2 lac. He is professional and deals with the investor in a nice and professional way', (SELECT id FROM opportunities WHERE name ILIKE 'আমার ফুডস' LIMIT 1));
INSERT INTO testimonials (name, brand_name, quote, related_opportunity_id) VALUES ('বিনিয়োগকারী', 'আমার ফুডস', 'আমার বিনিয়োগকৃত প্রতিষ্ঠানসমূহের মধ্যে সর্বাধিক flexible এবং transparent মনে হয়েছে তাঁকে। খাদ্যপণ্যের ব্যবসায় হওয়ায় সরকারি দপ্তরসমূহের বিভিন্ন কাগজপত্র থাকা জরুরি। বলামাত্রই তিনি সমস্ত আপডেট কাগজপত্র দেখিয়েছেন যা আমার কাছে তাঁর গ্রহণযোগ্যতা বহুলাংশে বাড়িয়ে দিয়েছে। এছাড়া চুক্তিপত্রের কিছু সংশোধন প্রস্তাবও তিনি খুব সহজেই গ্রহণ করেছেন যা তার আন্তরিকতারই বহি:প্রকাশ।', (SELECT id FROM opportunities WHERE name ILIKE 'আমার ফুডস' LIMIT 1));